create or replace function public.get_my_blocks() returns table(profile_id uuid,display_name text,district text,blocked_at timestamptz) language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'not_authenticated'; end if; return query select p.id,p.display_name,p.district,b.created_at from public.blocks b join public.profiles p on p.id=b.blocked_id where b.blocker_id=auth.uid() order by b.created_at desc; end; $$;
revoke execute on function public.get_my_blocks() from public,anon; grant execute on function public.get_my_blocks() to authenticated;
create or replace function public.get_my_report_history() returns table(report_id uuid,reported_user_id uuid,display_name text,category text,status public.report_status,created_at timestamptz) language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'not_authenticated'; end if; return query select r.id,p.id,p.display_name,r.category,r.status,r.created_at from public.reports r join public.profiles p on p.id=r.reported_user_id where r.reporter_id=auth.uid() order by r.created_at desc limit 100; end; $$;
revoke execute on function public.get_my_report_history() from public,anon; grant execute on function public.get_my_report_history() to authenticated;
